query ViewerEventQuery($id: Int!) {
  tournament(id: $id) {
    id
    endTime
    event {
      id
      registrationWindow {
        id
        status
        __typename
      }
      __typename
    }
    registrationConfig {
      promptForWheelchairAccess
      registrableUntil
      __typename
    }
    players(filter: {context: [VIEWER]}) {
      __typename
      ... on TeamTournamentPlayer {
        id
        registered
        notAttending
        eligible
        __typename
      }
      ... on SinglesTournamentPlayer {
        id
        registered
        notAttending
        eligible
        __typename
      }
      ... on WeeklyTournamentPlayer {
        id
        registered
        notAttending
        eligible
        __typename
      }
      ... on USAMTournamentPlayer {
        id
        __typename
      }
    }
    __typename
  }
}
